"use strict";(self.webpackChunkwebsite=self.webpackChunkwebsite||[]).push([["813"],{8919(e,t,n){n.r(t),n.d(t,{metadata:()=>a,default:()=>h,frontMatter:()=>r,contentTitle:()=>s,toc:()=>c,assets:()=>d});var a=JSON.parse('{"id":"how-to/hardware/3rdparty_getting_started","title":"Getting started with 3rd Party Hardware","description":"av \xb7 imported from live Hugo on 2026-10-07. Guides stay latest. Original page.","source":"@site/docs/how-to/hardware/3rdparty_getting_started.md","sourceDirName":"how-to/hardware","slug":"/how-to/hardware/3rdparty_getting_started","permalink":"/personal-av-docs/docs/how-to/hardware/3rdparty_getting_started","draft":false,"unlisted":false,"editUrl":"https://github.com/andreyjv/personal-av/tree/docs/documentation-revamp/PRD_documentation-revamp/website/docs/how-to/hardware/3rdparty_getting_started.md","tags":[],"version":"current","sidebarPosition":99,"frontMatter":{"title":"Getting started with 3rd Party Hardware","sidebar_label":"Getting started with 3rd Party Hardware","sidebar_position":99,"edition":"av","source":"https://doc.airvantage.net/av/howto/hardware/3rdparty_getting_started","format":"md"}}'),o=n(4848),i=n(8453);let r={title:"Getting started with 3rd Party Hardware",sidebar_label:"Getting started with 3rd Party Hardware",sidebar_position:99,edition:"av",source:"https://doc.airvantage.net/av/howto/hardware/3rdparty_getting_started",format:"md"},s,d={},c=[];function l(e){let t={a:"a",p:"p",strong:"strong",...(0,i.R)(),...e.components};return(0,o.jsxs)(o.Fragment,{children:[(0,o.jsxs)(t.p,{children:[":::note Edition\n",(0,o.jsx)(t.strong,{children:"av"})," \xb7 imported from live Hugo on 2026-10-07. Guides stay latest. ",(0,o.jsx)(t.a,{href:"https://doc.airvantage.net/av/howto/hardware/3rdparty_getting_started",children:"Original page"}),".\n:::"]}),"\n",(0,o.jsx)(t.p,{children:"Getting started with 3rd Party Hardware\nAs soon as you have an IP stack and the capability to do HTTP calls, you can use our HTTP API for devices. It doesn\u2019t give you all the fancy device management and application management features but it\u2019s really simple to use and it does the job for simple data exchange.\nFollow this tutorial to connect your device with AirVantage.\n1 /\nConnect\n2 /\nCollect\n3 /\nTest\n4 /\nAnalyze\n5 /\nAct\nWhich 3\nrd\nparty devices are supported?\nRaspberry Pi\nBeaglebone Black\nOthers*\n*) If your hardware has a mqtt library.\nAny issues ?\nIf you encounter any issue to set up your device, don\u2019t hesitate to use the\ndeveloper forum\nto benefit from the developer community experience.\nStep 1: Connect your device to AirVantage\nThe first step consists in declaring your system and your application on AirVantage.\nCreate an account\nRegister for an AirVantage Platform\naccount\n.\nYou will received an email when your account is up.\nRegister your system\nWhat is a system?\nA system represents:\nGateway/module which supplies the connectivity\nSIM card which give the network access (if any)\nSome applications running in the hardware (gateway/module/ any host like micro controller or processor)\nGo to Inventory > Systems\nClick on the \u201CCreate\u201D button above the table, a dialog is displayed:\n\u201CSystem\u201D field: Specify an optional name for your system.\nIn the \u201CDetails\u201D screen, create a new gateway and enter the identifier of the device in the \u201CSerial Number\u201D field.\nYou don\u2019t need to create or use a subscription\nSearch your application\nClick on Search application glass icon\nIn the new dialog box, select the My Applications tab\nSearch your application using its name (\nGeneric Greenhouse\n)\nIf you want to know more about how to declare an application on AirVantage and what it means, have a look at the\nApplication Howto\n.\nAssociate your application with your system\nClick on the application to select it.\nClick on the padlock and configure the password.\nClick on \u201CCreate\u201D\nIn the grid, select the newly created system and click on the \u201CActivate\u201D action\nStep 2: Design your application\nIn this step, we are going to send data using the MQTT API for devices. There\u2019s a huge choice of libraries on the web for many types of hardware and languages. Choose the one best suited to your hardware.\nYou can use\nREST API for devices\nas well. As soon as you have an IP stack and the capability to do HTTP calls, you can use our HTTP API for devices.\nIt doesn\u2019t give you all the fancy device management and application management features but it\u2019s really simple to use and it does the job for simple the data exchange. Read the following\narticle\nto learn how to use the REST API for devices to easily enable the communication with AirVantage from your embedded application.\nYou\u2019re ready to implement your embedded application. Some samples are available:\nUsing MQTT with BeagleBone Black in Javascript, see this\ntutorial\n.\nUsing MQTT with a raspberry Pi in c, see this\ntutorial\n.\nIf you don\u2019t find you device in this list, have a look to this\ngeneric tutorial\n.\nStep 3: Test your application\nFinally test your application by using this\ntutorial\n.\nStep 4: Define a dashboard and rules\nOnce your system communicates correctly and data values are stored in AirVantage, you may want to automatate the analysis by using rules and show them in a dashboard. Have a look at this\ntutorial\nto learn how to define a rule and design your operational dashboard.\nStep 5: Use the API\nOnce your system communicates correctly with AirVantage and data values can be browsed and displayed, you may want to get them in your specific application. Have a look at our\nAirVantage API\nto learn how to use this API to build powerful applications.\nSample code\nUsing MQTT with BeagleBone Black in Javascript, clone it on\ngithub\n.\nUsing MQTT with an OpenPicus in c, clone it on\ngithub\n.\nUsing MQTT with Raspberry Pi in C, clone it on\ngithub\n.\nUsing MQTT with ST Nucleo (mbed) in C, clone it on\ngithub\n.\nUsing REST with Raspberry Pi in python, clone it on\ngithub\n."})]})}function h(e={}){let{wrapper:t}={...(0,i.R)(),...e.components};return t?(0,o.jsx)(t,{...e,children:(0,o.jsx)(l,{...e})}):l(e)}},8453(e,t,n){n.d(t,{R:()=>r,x:()=>s});var a=n(6540);let o={},i=a.createContext(o);function r(e){let t=a.useContext(i);return a.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function s(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(o):e.components||o:r(e.components),a.createElement(i.Provider,{value:t},e.children)}}}]);